// Seven, Twos & Tens - Scripted variant. Generated by docs/feature-plans/game-bots/seven-twos-tens/tools/build.mjs; edit the sources, not this file.
// ============================================================================================
// Seven, Twos & Tens - the RULES KERNEL (pure: no table API, no Math.random, plain-JSON state).
//
// Card values are held as RANKS, an index into SV_FACES (lowest first): 3 4 5 6 8 9 11 12 13 14,
// then the three special cards 2 (reset), 7 (invisible) and 10 (explode), which may be played on
// anything. A deck has four copies of each of the 13 values; 5 or more players use two decks.
//
// House rulings (the printed rules leave these open; see README.md "Rulings"):
//   - A player who CAN play must play: the pile is picked up only when nothing in the hand (or
//     face-up cards) beats it. A face-down card is always turned over.
//   - After a 2, a 10 or four-of-a-kind the same player starts the new pile. They first draw back
//     up to three while the draw pile lasts, so that play comes from the hand like any other.
//   - Four of a kind clears the pile only when the four (or more) are played TOGETHER.
//   - Face-up cards of one value may be played together; hand and face-up cards never mix.
//   - The card turned over to start the game is the pile's first card: a 10 there explodes at
//     once (empty pile), a 2 or a 7 leaves anything playable.
//   - A game still running after SV_MAX_PLIES moves is a draw (a safety net; never seen in play).
// ============================================================================================

/** Card faces in rank order: rank r is the face SV_FACES[r]. */
const SV_FACES = [3, 4, 5, 6, 8, 9, 11, 12, 13, 14, 2, 7, 10];
const SV_RANKS = 13;
const SV_TWO = 10;
const SV_SEVEN = 11;
const SV_TEN = 12;
/** Most copies of one value a player can play at once (two decks hold eight). */
const SV_MAX_COUNT = 8;
/** Move numbers (= policy slots). */
const SV_M_CHOOSE = 0; // + rank: put one card of that value face up (setup)
const SV_M_PLAY = 13; // + rank * 8 + (count - 1): play `count` cards of that value
const SV_M_BLIND = 117; // + slot 0..2: turn over that face-down card and play it
const SV_M_PICKUP = 120; // take the whole pile into the hand
const SV_POLICY = 121;
const SV_MAX_PLIES = 2000;
const SV_PH_CHOOSE = 0;
const SV_PH_PLAY = 1;
const SV_PH_OVER = 2;
/** Encoding: SV_PLANES planes of SV_ROWS x 13 (a column per rank, a row per copy). */
const SV_PLANES = 31;
const SV_ROWS = 4;

/** What the last move did, for the table's log and animation. */
interface SvLast {
  /** Seat index that moved. */
  p: number;
  /** "choose" | "start" | "play" | "blind" | "fail" | "pickup". */
  k: string;
  /** The rank played, chosen or turned over (-1 for a pickup). */
  r: number;
  /** Cards played, or picked up. */
  n: number;
  /** The pile was cleared out of the game (a 10, or four of a kind). */
  burn: boolean;
  /** The same player plays again. */
  again: boolean;
  /** Cards drawn from the draw pile afterwards. */
  drew: number;
  /** "hand" | "up" | "down": where the played cards came from. */
  from: string;
}

interface SvState {
  seats: string[];
  decks: number;
  /** Per seat: how many of each rank are in the hand. */
  hand: number[][];
  /** Per seat: the three face-up slots (a rank, or -1 when empty). */
  up: number[][];
  /** Per seat: the three face-down slots (a rank, or -1 when empty). */
  down: number[][];
  /** Per seat: hand cards every player knows about (they were picked up off the pile), by rank. */
  known: number[][];
  /** The draw pile; the LAST element is the next card drawn. */
  draw: number[];
  /** The discard pile, oldest first. */
  pile: number[];
  /** Cards cleared out of the game, by rank. */
  burned: number[];
  /** The rank turned over to start the game (-1 before it is turned). */
  starter: number;
  who: number;
  first: number;
  ph: number;
  /** The player to move must start a new pile (after a 2, a 10 or four of a kind). */
  again: boolean;
  /** -1 while the game is on; a seat index; -2 for a draw. */
  win: number;
  ply: number;
  last: SvLast | null;
}

/** The match setup the table passes to `match.start`. */
interface SvSetup {
  seed: number;
  /** Seat index (into the seats list) that moves first. */
  first?: number;
  /** 1 or 2 decks; default 1 for up to four players, else 2. */
  decks?: number;
}

/** A small seeded generator (mulberry32): the deal is fixed by the setup's seed. */
function svRng(seed: number): () => number {
  let a = seed >>> 0;
  return function (): number {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function svZeros(): number[] {
  const a: number[] = [];
  for (let r = 0; r < SV_RANKS; r += 1) a.push(0);
  return a;
}

function svClone(s: SvState): SvState {
  return {
    seats: s.seats.slice(),
    decks: s.decks,
    hand: s.hand.map((h) => h.slice()),
    up: s.up.map((h) => h.slice()),
    down: s.down.map((h) => h.slice()),
    known: s.known.map((h) => h.slice()),
    draw: s.draw.slice(),
    pile: s.pile.slice(),
    burned: s.burned.slice(),
    starter: s.starter,
    who: s.who,
    first: s.first,
    ph: s.ph,
    again: s.again,
    win: s.win,
    ply: s.ply,
    last: s.last ? { p: s.last.p, k: s.last.k, r: s.last.r, n: s.last.n, burn: s.last.burn, again: s.last.again, drew: s.last.drew, from: s.last.from } : null
  };
}

function svSum(a: number[]): number {
  let n = 0;
  for (let i = 0; i < a.length; i += 1) n += a[i];
  return n;
}

function svSlots(a: number[]): number {
  let n = 0;
  for (let i = 0; i < a.length; i += 1) if (a[i] >= 0) n += 1;
  return n;
}

/** Every card a seat still holds: hand, face-up and face-down. */
function svCardsLeft(s: SvState, p: number): number {
  return svSum(s.hand[p]) + svSlots(s.up[p]) + svSlots(s.down[p]);
}

/** Where `p` plays from: 0 hand, 1 face-up cards, 2 face-down cards, 3 nothing left. */
function svSource(s: SvState, p: number): number {
  if (svSum(s.hand[p]) > 0) return 0;
  if (svSlots(s.up[p]) > 0) return 1;
  if (svSlots(s.down[p]) > 0) return 2;
  return 3;
}

/**
 * The rank a card must equal or beat: the newest card of the pile that is not a 7 (a 7 is
 * invisible). -1 when anything may be played: an empty pile, only 7s, or a 2 (a reset).
 */
function svToBeat(pile: number[]): number {
  for (let i = pile.length - 1; i >= 0; i -= 1) {
    const r = pile[i];
    if (r === SV_SEVEN) continue;
    if (r === SV_TWO) return -1;
    return r;
  }
  return -1;
}

/** May a card of rank `r` go on the pile now? The specials (ranks 10-12) always may. */
function svCanPlay(s: SvState, r: number): boolean {
  if (s.again) return true;
  const t = svToBeat(s.pile);
  return t < 0 || r >= t;
}

function svUpCount(s: SvState, p: number, r: number): number {
  let n = 0;
  for (let i = 0; i < 3; i += 1) if (s.up[p][i] === r) n += 1;
  return n;
}

function svPlayMove(r: number, count: number): number {
  return SV_M_PLAY + r * SV_MAX_COUNT + (count - 1);
}

function svInitial(seats: string[], setup?: unknown): SvState {
  const n = seats.length;
  const su = (setup && typeof setup === "object" ? setup : {}) as Partial<SvSetup>;
  const seed = typeof su.seed === "number" && isFinite(su.seed) ? Math.floor(su.seed) : 1;
  const decks = su.decks === 1 || su.decks === 2 ? su.decks : n >= 5 ? 2 : 1;
  const first = typeof su.first === "number" && su.first >= 0 && su.first < n ? Math.floor(su.first) : 0;
  const cards: number[] = [];
  for (let d = 0; d < decks; d += 1) for (let r = 0; r < SV_RANKS; r += 1) for (let c = 0; c < 4; c += 1) cards.push(r);
  const rnd = svRng(seed);
  for (let i = cards.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rnd() * (i + 1));
    const t = cards[i];
    cards[i] = cards[j];
    cards[j] = t;
  }
  const s: SvState = {
    seats: seats.slice(),
    decks,
    hand: [],
    up: [],
    down: [],
    known: [],
    draw: cards,
    pile: [],
    burned: svZeros(),
    starter: -1,
    who: first,
    first,
    ph: SV_PH_CHOOSE,
    again: false,
    win: -1,
    ply: 0,
    last: null
  };
  for (let p = 0; p < n; p += 1) {
    s.hand.push(svZeros());
    s.known.push(svZeros());
    s.up.push([-1, -1, -1]);
    s.down.push([-1, -1, -1]);
  }
  // Three face down each, one at a time round the table from the first player, then six to the hand.
  for (let slot = 0; slot < 3; slot += 1) {
    for (let i = 0; i < n; i += 1) {
      const p = (first + i) % n;
      const c = s.draw.pop();
      if (c !== undefined) s.down[p][slot] = c;
    }
  }
  for (let k = 0; k < 6; k += 1) {
    for (let i = 0; i < n; i += 1) {
      const p = (first + i) % n;
      const c = s.draw.pop();
      if (c !== undefined) s.hand[p][c] += 1;
    }
  }
  return s;
}

function svCurrentPlayer(s: SvState): string {
  return s.seats[s.who];
}

function svLegalMoves(s: SvState): number[] {
  const out: number[] = [];
  if (s.ph === SV_PH_OVER) return out;
  const p = s.who;
  if (s.ph === SV_PH_CHOOSE) {
    for (let r = 0; r < SV_RANKS; r += 1) if (s.hand[p][r] > 0) out.push(SV_M_CHOOSE + r);
    return out;
  }
  const src = svSource(s, p);
  if (src === 0 || src === 1) {
    for (let r = 0; r < SV_RANKS; r += 1) {
      const have = src === 0 ? s.hand[p][r] : svUpCount(s, p, r);
      if (have <= 0 || !svCanPlay(s, r)) continue;
      for (let k = 1; k <= Math.min(have, SV_MAX_COUNT); k += 1) out.push(svPlayMove(r, k));
    }
    if (out.length === 0) out.push(SV_M_PICKUP);
    return out;
  }
  if (src === 2) {
    for (let slot = 0; slot < 3; slot += 1) if (s.down[p][slot] >= 0) out.push(SV_M_BLIND + slot);
    return out;
  }
  // A seat with nothing left has won, so this is never reached in a game that is on.
  out.push(SV_M_PICKUP);
  return out;
}

/** Draw back up to three cards while the draw pile lasts. Returns how many were drawn. */
function svRefill(s: SvState, p: number): number {
  let drew = 0;
  while (svSum(s.hand[p]) < 3 && s.draw.length > 0) {
    const c = s.draw.pop();
    if (c === undefined) break;
    s.hand[p][c] += 1;
    drew += 1;
  }
  return drew;
}

/** Turn over the starting card once every player has chosen their face-up cards. */
function svStart(s: SvState): void {
  s.ph = SV_PH_PLAY;
  s.who = s.first;
  const c = s.draw.pop();
  let burn = false;
  if (c !== undefined) {
    s.starter = c;
    if (c === SV_TEN) {
      s.burned[c] += 1;
      burn = true;
    } else s.pile.push(c);
  }
  s.last = { p: s.first, k: "start", r: c === undefined ? -1 : c, n: 1, burn, again: false, drew: 0, from: "draw" };
}

/** Put `k` cards of rank `r` (already taken from where they were) on the pile, then resolve it. */
function svResolvePlay(s: SvState, p: number, r: number, k: number, kind: string, from: string): void {
  for (let i = 0; i < k; i += 1) s.pile.push(r);
  const burn = r === SV_TEN || k >= 4;
  if (burn) {
    for (let i = 0; i < s.pile.length; i += 1) s.burned[s.pile[i]] += 1;
    s.pile = [];
  }
  const drew = svRefill(s, p);
  let again = burn || r === SV_TWO;
  if (svCardsLeft(s, p) === 0) {
    s.win = p;
    s.ph = SV_PH_OVER;
    again = false;
  }
  s.again = again;
  if (!again && s.win < 0) s.who = (p + 1) % s.seats.length;
  s.last = { p, k: kind, r, n: k, burn, again, drew, from };
}

function svPickup(s: SvState, p: number, kind: string, r: number): void {
  const n = s.pile.length;
  for (let i = 0; i < n; i += 1) {
    s.hand[p][s.pile[i]] += 1;
    s.known[p][s.pile[i]] += 1;
  }
  s.pile = [];
  s.again = false;
  const drew = svRefill(s, p);
  s.who = (p + 1) % s.seats.length;
  s.last = { p, k: kind, r, n, burn: false, again: false, drew, from: kind === "fail" ? "down" : "pile" };
}

function svApply(s0: SvState, m: number): SvState {
  const s = svClone(s0);
  if (s.ph === SV_PH_OVER) return s;
  const p = s.who;
  s.ply += 1;
  if (s.ph === SV_PH_CHOOSE) {
    const r = m - SV_M_CHOOSE;
    if (r < 0 || r >= SV_RANKS || s.hand[p][r] <= 0) throw new Error("Seven, Twos & Tens: not a legal choice: " + m);
    s.hand[p][r] -= 1;
    const slot = s.up[p].indexOf(-1);
    s.up[p][slot] = r;
    s.last = { p, k: "choose", r, n: 1, burn: false, again: false, drew: 0, from: "hand" };
    if (svSlots(s.up[p]) >= 3) {
      const n = s.seats.length;
      const next = (p + 1) % n;
      if (next === s.first) svStart(s);
      else s.who = next;
    }
    return s;
  }
  const src = svSource(s, p);
  if (m === SV_M_PICKUP) {
    if (src !== 0 && src !== 1) throw new Error("Seven, Twos & Tens: nothing to pick up with face-down cards to play");
    svPickup(s, p, "pickup", -1);
  } else if (m >= SV_M_BLIND && m < SV_M_BLIND + 3) {
    const slot = m - SV_M_BLIND;
    const r = s.down[p][slot];
    if (src !== 2 || r < 0) throw new Error("Seven, Twos & Tens: not a legal face-down card: " + m);
    s.down[p][slot] = -1;
    if (svCanPlay(s, r)) svResolvePlay(s, p, r, 1, "blind", "down");
    else {
      s.pile.push(r);
      svPickup(s, p, "fail", r);
    }
  } else if (m >= SV_M_PLAY && m < SV_M_BLIND) {
    const r = Math.floor((m - SV_M_PLAY) / SV_MAX_COUNT);
    const k = ((m - SV_M_PLAY) % SV_MAX_COUNT) + 1;
    if (!svCanPlay(s, r)) throw new Error("Seven, Twos & Tens: that card does not beat the pile: " + m);
    if (src === 0) {
      if (s.hand[p][r] < k) throw new Error("Seven, Twos & Tens: not enough cards in hand: " + m);
      s.hand[p][r] -= k;
      s.known[p][r] = Math.max(0, Math.min(s.known[p][r] - k, s.hand[p][r]));
      svResolvePlay(s, p, r, k, "play", "hand");
    } else if (src === 1) {
      if (svUpCount(s, p, r) < k) throw new Error("Seven, Twos & Tens: not enough face-up cards: " + m);
      let left = k;
      for (let i = 0; i < 3 && left > 0; i += 1) {
        if (s.up[p][i] === r) {
          s.up[p][i] = -1;
          left -= 1;
        }
      }
      svResolvePlay(s, p, r, k, "play", "up");
    } else throw new Error("Seven, Twos & Tens: no hand or face-up cards to play: " + m);
  } else throw new Error("Seven, Twos & Tens: unknown move " + m);
  if (s.win < 0 && s.ply >= SV_MAX_PLIES) {
    s.win = -2;
    s.ph = SV_PH_OVER;
  }
  return s;
}

function svTerminal(s: SvState): { value: Record<string, number> } | null {
  if (s.ph !== SV_PH_OVER) return null;
  const value: Record<string, number> = {};
  const n = s.seats.length;
  for (let p = 0; p < n; p += 1) value[s.seats[p]] = s.win === -2 ? 0 : p === s.win ? 1 : -1 / Math.max(1, n - 1);
  return { value };
}

/**
 * The position as the player to move sees it: SV_PLANES planes of SV_ROWS x 13. A column is a rank
 * (rank order, so neighbouring columns are neighbouring values); a count is drawn as a thermometer
 * down the rows (row k lit when there are more than k). Hidden cards appear only as counts: this
 * reads nothing the mover cannot see, so it is the same for every determinization of a position.
 */
function svEncode(s: SvState): Float32Array {
  const W = SV_RANKS;
  const H = SV_ROWS;
  const out = new Float32Array(SV_PLANES * H * W);
  const p = s.who;
  const n = s.seats.length;
  const nx = (p + 1) % n;
  const cell = (plane: number, row: number, col: number, v: number): void => {
    out[(plane * H + row) * W + col] = v;
  };
  const thermo = (plane: number, counts: number[]): void => {
    for (let r = 0; r < W; r += 1) {
      const c = counts[r];
      if (c <= 0) continue;
      for (let k = 0; k < H - 1; k += 1) cell(plane, k, r, c > k ? 1 : 0);
      cell(plane, H - 1, r, Math.min(1, Math.max(0, c - (H - 1)) / 5));
    }
  };
  const column = (plane: number, r: number, v: number): void => {
    for (let k = 0; k < H; k += 1) cell(plane, k, r, v);
  };
  const fill = (plane: number, v: number): void => {
    for (let i = 0; i < H * W; i += 1) out[plane * H * W + i] = v;
  };
  const upCounts = (q: number): number[] => {
    const a = svZeros();
    for (let i = 0; i < 3; i += 1) if (s.up[q][i] >= 0) a[s.up[q][i]] += 1;
    return a;
  };
  const t = s.again ? -1 : svToBeat(s.pile);
  const pileCount = svZeros();
  for (let i = 0; i < s.pile.length; i += 1) pileCount[s.pile[i]] += 1;
  // What the mover can account for: everything else is unseen (opponents' unknown hand cards, every face-down card, the draw pile).
  const unseen = svZeros();
  for (let r = 0; r < W; r += 1) unseen[r] = 4 * s.decks - s.hand[p][r] - pileCount[r] - s.burned[r];
  const othersUp = svZeros();
  const othersKnown = svZeros();
  let othersHand = 0;
  let othersDown = 0;
  for (let q = 0; q < n; q += 1) {
    for (let i = 0; i < 3; i += 1) if (s.up[q][i] >= 0) unseen[s.up[q][i]] -= 1;
    if (q === p) continue;
    for (let r = 0; r < W; r += 1) unseen[r] -= s.known[q][r];
    if (q === nx) continue;
    othersHand += svSum(s.hand[q]);
    othersDown += svSlots(s.down[q]);
    for (let i = 0; i < 3; i += 1) if (s.up[q][i] >= 0) othersUp[s.up[q][i]] += 1;
    for (let r = 0; r < W; r += 1) othersKnown[r] += s.known[q][r];
  }
  thermo(0, s.hand[p]);
  thermo(1, s.known[p]);
  thermo(2, upCounts(p));
  thermo(3, pileCount);
  thermo(4, s.burned);
  thermo(5, unseen);
  thermo(6, s.known[nx]);
  thermo(7, upCounts(nx));
  thermo(8, othersUp);
  thermo(9, othersKnown);
  // The newest pile cards, newest in row 0: a 7 shows the card it hides one row down.
  for (let k = 0; k < H && k < s.pile.length; k += 1) cell(10, k, s.pile[s.pile.length - 1 - k], 1);
  if (t >= 0) column(11, t, 1);
  for (let r = 0; r < W; r += 1) if (svCanPlay(s, r)) column(12, r, 1);
  if (s.ph === SV_PH_PLAY) {
    const legal = svLegalMoves(s);
    for (let i = 0; i < legal.length; i += 1) {
      const m = legal[i];
      if (m < SV_M_PLAY || m >= SV_M_BLIND) continue;
      const k = (m - SV_M_PLAY) % SV_MAX_COUNT;
      if (k < H) cell(13, k, Math.floor((m - SV_M_PLAY) / SV_MAX_COUNT), 1);
    }
  }
  fill(14, svSlots(s.down[p]) / 3);
  fill(15, t < 0 ? 1 : 0);
  fill(16, Math.min(1, s.pile.length / 26));
  fill(17, Math.min(1, s.draw.length / 40));
  fill(18, Math.min(1, svSum(s.hand[nx]) / 20));
  fill(19, svSlots(s.down[nx]) / 3);
  fill(20, Math.min(1, othersHand / 40));
  fill(21, Math.min(1, othersDown / 18));
  fill(22, s.again ? 1 : 0);
  fill(23, s.ph === SV_PH_CHOOSE ? 1 : 0);
  const src = svSource(s, p);
  fill(24, src === 0 ? 1 : 0);
  fill(25, src === 1 ? 1 : 0);
  fill(26, src === 2 ? 1 : 0);
  fill(27, n / 8);
  fill(28, s.decks / 2);
  fill(29, Math.min(1, svCardsLeft(s, nx) / 30));
  fill(30, Math.min(1, svCardsLeft(s, p) / 30));
  return out;
}

/** How hard a seat's position is to empty: cards left, low cards weigh more, specials less. */
function svBurden(s: SvState, q: number): number {
  let cost = 0;
  for (let r = 0; r < SV_RANKS; r += 1) {
    const c = s.hand[q][r];
    if (c === 0) continue;
    if (r >= SV_TWO) cost += 0.45 * c;
    else if (r <= 3) cost += 1.35 * c;
    else cost += (1.15 - 0.03 * r) * c;
  }
  for (let i = 0; i < 3; i += 1) {
    const u = s.up[q][i];
    if (u >= 0) cost += u >= SV_TWO ? 0.4 : 1.1 - 0.04 * u;
    if (s.down[q][i] >= 0) cost += 1;
  }
  return cost;
}

/** Plies a heuristic playout may run before it is scored on the cards left instead. */
const SV_PLAYOUT_PLIES = 400;

/** The burden comparison alone, in [-1, 1], for seat `p`. */
function svBurdenValue(s: SvState, p: number): number {
  const mine = svBurden(s, p);
  let best = Infinity;
  for (let q = 0; q < s.seats.length; q += 1) if (q !== p) best = Math.min(best, svBurden(s, q));
  if (!isFinite(best)) return 0;
  const x = (best - mine) / 5;
  const e = Math.exp(2 * Math.max(-10, Math.min(10, x)));
  return (e - 1) / (e + 1);
}

/**
 * The kernel's estimate for the player to move, in [-1, 1]: one greedy playout of the position to
 * the end (it is deterministic, and a search hands it a determinized copy), blended with the
 * cards-left comparison so it is never a bare coin. A one-ply score of the cards alone could not
 * tell the moves apart, and searching with it lost four games in five to the greedy bot.
 */
function svHeuristic(s: SvState): number {
  const p = s.who;
  const n = s.seats.length;
  let x = s;
  for (let i = 0; i < SV_PLAYOUT_PLIES && x.ph !== SV_PH_OVER; i += 1) x = svApply(x, svGreedyMove(x));
  let result = 0;
  if (x.ph !== SV_PH_OVER) result = svBurdenValue(x, p);
  else if (x.win === p) result = 1;
  else if (x.win >= 0) result = -1 / Math.max(1, n - 1);
  return 0.7 * result + 0.3 * svBurdenValue(s, p);
}

/**
 * A copy of `s` with everything `seat` cannot see dealt again at random: the other players' hand
 * cards that nobody saw them pick up, every face-down card (the seat's own too) and the order of
 * the draw pile. The counts per place stay the same, so the seat's own legal moves do not change.
 */
function svDeterminize(s0: SvState, seat: number, random: () => number): SvState {
  const s = svClone(s0);
  const n = s.seats.length;
  const pool: number[] = [];
  const hidden: number[] = [];
  for (let q = 0; q < n; q += 1) {
    if (q !== seat) {
      let unknown = 0;
      for (let r = 0; r < SV_RANKS; r += 1) {
        const u = s.hand[q][r] - Math.min(s.known[q][r], s.hand[q][r]);
        for (let i = 0; i < u; i += 1) pool.push(r);
        unknown += u;
        s.hand[q][r] -= u;
      }
      hidden.push(unknown);
    } else hidden.push(0);
    for (let i = 0; i < 3; i += 1) if (s.down[q][i] >= 0) pool.push(s.down[q][i]);
  }
  for (let i = 0; i < s.draw.length; i += 1) pool.push(s.draw[i]);
  for (let i = pool.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    const t = pool[i];
    pool[i] = pool[j];
    pool[j] = t;
  }
  let at = 0;
  for (let q = 0; q < n; q += 1) {
    for (let i = 0; i < hidden[q]; i += 1) s.hand[q][pool[at++]] += 1;
    for (let i = 0; i < 3; i += 1) if (s.down[q][i] >= 0) s.down[q][i] = pool[at++];
  }
  for (let i = 0; i < s.draw.length; i += 1) s.draw[i] = pool[at++];
  return s;
}

const kernel: RulesKernel<SvState, number> & { determinize(s: SvState, seat: string, random: () => number): SvState } = {
  id: "seven-twos-tens",
  version: 1,
  initial: (seats, setup) => svInitial(seats, setup),
  currentPlayer: (s) => svCurrentPlayer(s),
  legalMoves: (s) => svLegalMoves(s),
  apply: (s, m) => svApply(s, m),
  terminal: (s) => svTerminal(s),
  encode: (s) => svEncode(s),
  encoding: { planes: SV_PLANES, height: SV_ROWS, width: SV_RANKS },
  policySize: SV_POLICY,
  moveIndex: (m) => m,
  moveAt: (i) => i,
  heuristic: (s) => svHeuristic(s),
  determinize: (s, seat, random) => svDeterminize(s, Math.max(0, s.seats.indexOf(seat)), random)
};

// ------------------------------------------------------------------------- reference bots --

/**
 * The plain strategy most people play: keep the specials, put the lowest card that beats the pile
 * down (every copy of it), pick the strongest cards to lie face up.
 */
function svGreedyMove(s: SvState): number {
  const legal = svLegalMoves(s);
  if (legal.length <= 1) return legal[0];
  if (s.ph === SV_PH_CHOOSE) {
    let best = legal[0];
    for (const m of legal) if (m > best) best = m;
    return best;
  }
  let best = -1;
  let bestKey = Infinity;
  for (const m of legal) {
    if (m < SV_M_PLAY || m >= SV_M_BLIND) continue;
    const r = Math.floor((m - SV_M_PLAY) / SV_MAX_COUNT);
    const k = ((m - SV_M_PLAY) % SV_MAX_COUNT) + 1;
    // Lowest value first, every copy; among the specials a 7, then a 2, then a 10 - unless the pile
    // is big enough to be worth exploding (measured: +4% over 2-7-10 against the same bot).
    let key = r * 10 - k;
    if (r === SV_SEVEN) key = 94 - k;
    else if (r === SV_TEN && s.pile.length >= 12) key = 96 - k;
    if (key < bestKey) {
      bestKey = key;
      best = m;
    }
  }
  if (best >= 0) return best;
  return legal[0];
}

/**
 * Perfect-information Monte Carlo: deal the cards the mover cannot see again `worlds` times, play
 * each legal move in each world and finish the game greedily, and keep the move that won most. It
 * never looks at the real hidden cards. `random` drives the re-deals (the table passes Math.random).
 */
function svPimcMove(s: SvState, worlds: number, random: () => number): number {
  const legal = svLegalMoves(s);
  if (legal.length <= 1) return legal[0];
  const p = s.who;
  const n = s.seats.length;
  const score: number[] = legal.map(() => 0);
  for (let w = 0; w < worlds; w += 1) {
    const det = svDeterminize(s, p, random);
    for (let i = 0; i < legal.length; i += 1) {
      let x = svApply(det, legal[i]);
      for (let ply = 0; ply < SV_PLAYOUT_PLIES && x.ph !== SV_PH_OVER; ply += 1) x = svApply(x, svGreedyMove(x));
      if (x.ph !== SV_PH_OVER) score[i] += 0.5 * (1 + svBurdenValue(x, p)) / n;
      else if (x.win === p) score[i] += 1;
    }
  }
  let best = 0;
  for (let i = 1; i < legal.length; i += 1) if (score[i] > score[best]) best = i;
  return legal[best];
}

