const TX_FALLBACK_TABLE_ZONES: SeatZoneInfo[] = [{"seat":null,"id":"table-zone-1","name":"Deck","zoneType":"area","primary":false,"position":[0,1.816,0],"size":[0.245,0.1,0.32],"rotationY":180},{"seat":null,"id":"table-zone-2","name":"PlayArea","zoneType":"area","primary":false,"position":[0.2706804573535919,1.8159999995529652,0],"size":[0.245,0.1,0.32],"rotationY":180},{"seat":null,"id":"table-zone-3","name":"Discard","zoneType":"area","primary":false,"position":[-0.6303132176399231,1.8159999995529652,0],"size":[0.245,0.1,0.32],"rotationY":180}];
/** The pack deck's customDeck metadata: every card the script spawns draws its face and back from it. */
const TX_DECK_ART: Record<string, unknown> = {"definitionId":"deck-e682a22c-13b1-4b85-afd6-445d88a47246","face":{"texturePath":"assets/textures/decks/deck-1/sheet-1.webp","columns":7,"rows":2,"cardCount":13,"cardWidthPx":512,"cardHeightPx":716},"uniqueBacks":false,"back":{"kind":"single","texturePath":"7210-back.webp"},"sideways":false,"backIsHidden":false,"cardFields":[],"deckFields":[],"data":{},"cards":[{"cardId":"card-1","label":"2","faceIndex":0,"count":4},{"cardId":"card-2","label":"3","faceIndex":1,"count":4},{"cardId":"card-3","label":"4","faceIndex":2,"count":4},{"cardId":"card-4","label":"5","faceIndex":3,"count":4},{"cardId":"card-5","label":"6","faceIndex":4,"count":4},{"cardId":"card-6","label":"7","faceIndex":5,"count":4},{"cardId":"card-7","label":"8","faceIndex":6,"count":4},{"cardId":"card-8","label":"9","faceIndex":7,"count":4},{"cardId":"card-9","label":"10","faceIndex":8,"count":4},{"cardId":"card-10","label":"11","faceIndex":9,"count":4},{"cardId":"card-11","label":"12","faceIndex":10,"count":4},{"cardId":"card-12","label":"13","faceIndex":11,"count":4},{"cardId":"card-13","label":"14","faceIndex":12,"count":4}]};
/** Height of the table surface under the pack's deck (its bottom face), feet. */
const TX_SURFACE_Y = 1.7704;

// ============================================================================================
// Seven, Twos & Tens - the TABLE half of the scene script.
//
// The rules live in the kernel above (`kernel`, pure). This half:
//   - seats the game (every occupied seat, clockwise; nobody seated = practice against a bot),
//   - starts a match with the kernel and a setup (shuffle seed, first player, decks),
//   - draws the kernel state on the table after every move: hands in the seats' real hand zones,
//     face-down and face-up cards in CardZone1-3, the pile on the PlayArea, the draw pile on the
//     Deck zone, cleared cards on the Discard zone,
//   - takes moves from clicks, drags onto the pile and HUD buttons, and plays the bots.
// Every module-level name here starts with "tx" so the kernel extractor never mistakes table code
// for a kernel helper.
// ============================================================================================

const TX_SEAT_ORDER = ["red", "blue", "green", "yellow", "purple", "orange", "pink", "cyan"];
const TX_TAG = "s7210";
const TX_DEAL_TAG = "s7210-deal";
/** Seconds between two bot moves, so people can follow them. */
const TX_BOT_PACE = 0.8;
/** The newest pile cards drawn loose and fanned; the older ones are one face-up stack under them. */
const TX_PILE_LOOSE = 5;
/** Thickness of one card in a stack (the pack deck is 0.0512 ft for 52 cards). */
const TX_CARD_T = 0.000985;
/** How far (feet) a face-up card sits from the face-down card under it, toward the middle of the table. */
const TX_UP_SHIFT = 0.05;
/** PIMC worlds per bot difficulty (Card Shark). */
const TX_SHARK_WORLDS: { [difficulty: string]: number } = { easy: 6, normal: 16, hard: 48 };
/** The trained network's model id per difficulty, and its search. */
const TX_AI_LEVELS: { [difficulty: string]: { modelId: string; sims: number; dets: number; temperature: number } } = {
  easy: { modelId: "seven-net", sims: 16, dets: 1, temperature: 0.6 },
  normal: { modelId: "seven-net", sims: 64, dets: 2, temperature: 0 },
  hard: { modelId: "seven-net", sims: 160, dets: 4, temperature: 0 }
};

type TxEnt = { id: string; r: number };
type TxMatchStart = (options: { seats?: readonly string[]; kernel?: RulesKernel<SvState, number>; setup?: unknown }) => Promise<MatchInfo>;

let txState: SvState | null = null;
let txSetup: SvSetup | null = null;
/** Seat ids in kernel order (clockwise). */
let txSeats: string[] = [];
/** Nobody (or one person) is seated: kernel seat 0 is played by whoever is at the table, the rest by the script. */
let txPractice = false;
let txRecording = false;
let txOver = false;
let txHumanMoved = false;
let txStarting = false;
let txRestartQueued = false;
let txChain: Promise<void> = Promise.resolve();
let txZones: { [seat: string]: { [name: string]: SeatZoneInfo } } = {};
let txTableZones: { [name: string]: SeatZoneInfo } = {};
let txSurface = TX_SURFACE_Y;
let txCopy = 0;
/** Cards each seat holds in its hand, as entities (dealt into the real hand zone, or laid in a row). */
const txHand: { [seat: string]: TxEnt[] } = {};
/** Whether a seat's hand is the platform's private hand zone (a claimed seat) or a row on the table. */
const txRealHand: { [seat: string]: boolean } = {};
const txUp: { [seat: string]: (TxEnt | null)[] } = {};
const txDown: { [seat: string]: (TxEnt | null)[] } = {};
/** Loose pile cards by pile index. */
let txLoose: { [index: number]: TxEnt } = {};
let txBase: { id: string; key: string } | null = null;
let txDrawPile: { id: string; n: number } | null = null;
let txOutPile: { id: string; n: number } | null = null;
/** Face-up picks each person made in the choose picker (ranks), applied when the kernel reaches their seat. */
const txChoices: { [seatIndex: number]: number[] } = {};
/** Seats whose face-up picker is open. */
const txChoosing: { [seat: string]: boolean } = {};
const txHudCache: { [k: string]: UiValue } = {};
/** The outlines last set (audience + ids), so a redraw that changes nothing sends nothing. */
let txLastHighlight = "";
/** Kernel seats that forfeited a match with more than two players: the table plays their cards (greedily) so the game can end. */
const txGone: { [seatIndex: number]: boolean } = {};
/** Practice: a bot plays the person's seat too ("Let a bot play my cards"), to watch a whole game. */
let txAutoplay = false;

function txRun(fn: () => Promise<void>): Promise<void> {
  txChain = txChain.then(fn).catch((error) => {
    world.log("Seven, Twos & Tens error: " + txDescribe(error));
  });
  return txChain;
}

function txDescribe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

// --------------------------------------------------------------------------------- names --

function txFace(r: number): number {
  return SV_FACES[r];
}

function txCardId(r: number): string {
  txCopy += 1;
  return "card-" + (SV_FACES[r] - 1) + "#" + (100 + txCopy);
}

const TX_NUMBER_WORDS = ["no", "one", "two", "three", "four", "five", "six", "seven", "eight"];

/** "a 9", "two 9s", "an 8", "an 11". */
function txCards(r: number, n: number): string {
  const face = txFace(r);
  if (n === 1) return (face === 8 || face === 11 ? "an " : "a ") + face;
  return (TX_NUMBER_WORDS[n] || String(n)) + " " + face + "s";
}

function txSeatName(q: number): string {
  const id = txSeats[q];
  if (txPractice) return q === 0 ? "Player" : "Bot";
  const p = world.getPlayers().find((x) => x.seat === id);
  if (p && p.displayName) return p.displayName;
  return "Player " + (TX_SEAT_ORDER.indexOf(id) + 1);
}

// --------------------------------------------------------------------------------- seats --

function txIsBotSeat(q: number): boolean {
  if (txPractice) return q !== 0 || txAutoplay;
  if (txGone[q]) return true;
  const id = txSeats[q];
  return world.getPlayers().some((p) => p.seat === id && p.isBot);
}

function txHumanSeat(q: number): boolean {
  return !txIsBotSeat(q);
}

/** The kernel seat a click or press came from (practice: anyone plays seat 0), or -1. */
function txSeatOf(seat: string | null, actor: string | null): number {
  if (txPractice) return 0;
  let id = seat;
  if (!id && actor) {
    const p = world.getPlayers().find((x) => x.peerId === actor);
    id = p ? p.seat : null;
  }
  return id ? txSeats.indexOf(id) : -1;
}

function txChooseSeats(): void {
  const occupied = TX_SEAT_ORDER.filter((seat) => world.getPlayers().some((p) => p.seat === seat));
  if (occupied.length >= 2) {
    txSeats = occupied;
    txPractice = false;
    return;
  }
  // Practice: the one person (or nobody) against a bot the script plays.
  const mine = occupied.length === 1 ? occupied[0] : "red";
  const at = TX_SEAT_ORDER.indexOf(mine);
  txSeats = [mine, TX_SEAT_ORDER[(at + 4) % TX_SEAT_ORDER.length]];
  txPractice = true;
}

// --------------------------------------------------------------------------------- geometry --

async function txLoadZones(): Promise<boolean> {
  txZones = {};
  for (const seat of txSeats) {
    let list = await world.getSeatZones(seat);
    // An unclaimed seat (practice, a preview) has no live zones: use the authored ones.
    if (!list.some((z) => z.name === "CardZone1")) list = TX_FALLBACK_ZONES[seat] || list;
    const byName: { [name: string]: SeatZoneInfo } = {};
    for (const z of list) byName[z.name] = z;
    txZones[seat] = byName;
    txRealHand[seat] = !txPractice && (await world.getSeatZones(seat)).some((z) => z.zoneType === "hand");
  }
  txTableZones = {};
  let table = (await world.getSeatZones()).filter((z) => z.seat === null);
  if (!table.some((z) => z.name === "PlayArea")) table = TX_FALLBACK_TABLE_ZONES;
  for (const z of table) txTableZones[z.name] = z;
  return txSeats.every((seat) => !!txZones[seat] && !!txZones[seat]["CardZone1"]) && !!txTableZones["PlayArea"];
}

/** A point in a zone's frame: local +x runs to the seat's left, local +z toward the middle of the table. */
function txLocal(zone: SeatZoneInfo, lx: number, lz: number, lift: number): Vec3 {
  const a = (zone.rotationY * Math.PI) / 180;
  return [zone.position[0] + lx * Math.cos(a) + lz * Math.sin(a), txSurface + 0.002 + lift, zone.position[2] - lx * Math.sin(a) + lz * Math.cos(a)];
}

/** The yaw that makes a card read upright for the seat that owns `zone`. */
function txZoneYaw(zone: SeatZoneInfo): number {
  return (((zone.rotationY + 180) % 360) + 360) % 360;
}

function txInZone(z: SeatZoneInfo, pos: Vec3, margin: number): boolean {
  const a = (z.rotationY * Math.PI) / 180;
  const dx = pos[0] - z.position[0];
  const dz = pos[2] - z.position[2];
  const lx = dx * Math.cos(a) - dz * Math.sin(a);
  const lz = dx * Math.sin(a) + dz * Math.cos(a);
  return Math.abs(lx) <= z.size[0] / 2 + margin && Math.abs(lz) <= z.size[2] / 2 + margin;
}

function txTableZone(name: string): SeatZoneInfo {
  const z = txTableZones[name];
  if (z) return z;
  const fallback = TX_FALLBACK_TABLE_ZONES.find((x) => x.name === name);
  return fallback || TX_FALLBACK_TABLE_ZONES[0];
}

// --------------------------------------------------------------------------------- entities --

/** Where the script spawns before moving a card into place (a seat's card zones refuse a spawn into them). */
function txSpawnPoint(): Vec3 {
  return [0, txSurface + 0.35, 0];
}

async function txDestroy(id: string): Promise<void> {
  const h = await world.getObjectById(id);
  if (h) h.destroy();
}

/** A locked loose card. `r` null: a face-down card whose face nobody may learn (it carries a stand-in id). */
async function txSpawnCard(r: number | null, pos: Vec3, yaw: number, faceDown: boolean, name: string): Promise<string | null> {
  const handle = (await world.spawnObject({
    kind: "card",
    presetId: "card-standard",
    name,
    position: txSpawnPoint(),
    rotation: [0, yaw, 0],
    metadata: { customDeck: TX_DECK_ART, cardId: r === null ? "card-1" : txCardId(r), standardPresetId: "card-standard" },
    tags: [TX_TAG]
  })) as CardObject | null;
  if (!handle) return null;
  handle.setPosition(pos);
  handle.setRotation([0, yaw, 0]);
  if (faceDown ? handle.faceUp !== false : handle.faceUp === false) handle.flip();
  handle.lock();
  return handle.id;
}

/** A locked pile of `n` cards (`faces` newest first, or null for stand-in backs). One card is spawned as a card. */
async function txSpawnStack(faces: number[] | null, n: number, pos: Vec3, yaw: number, faceDown: boolean, name: string): Promise<string | null> {
  if (n <= 0) return null;
  if (n === 1) return txSpawnCard(faces ? faces[0] : null, pos, yaw, faceDown, name);
  const cards: { cardId: string; faceDown: boolean }[] = [];
  for (let i = 0; i < n; i += 1) cards.push({ cardId: faces ? txCardId(faces[i]) : "card-1", faceDown });
  const handle = await world.spawnObject({
    kind: "deck",
    presetId: "deck-standard",
    name,
    position: txSpawnPoint(),
    rotation: [0, yaw, 0],
    metadata: { customDeck: TX_DECK_ART, cards, standardPresetId: "deck-standard" },
    tags: [TX_TAG]
  });
  if (!handle) return null;
  handle.setPosition([pos[0], pos[1] + (n * TX_CARD_T) / 2, pos[2]]);
  handle.setRotation([0, yaw, 0]);
  handle.lock();
  return handle.id;
}

/** Deal one card into a seat's real hand: a one-card pile, dealt with the platform's own deal (private to the seat). */
async function txDealToHand(seat: string, r: number): Promise<string | null> {
  const pile = (await world.spawnObject({
    kind: "deck",
    presetId: "deck-standard",
    name: "Dealing",
    position: txSpawnPoint(),
    metadata: { customDeck: TX_DECK_ART, cards: [{ cardId: txCardId(r), faceDown: true }], standardPresetId: "deck-standard" },
    tags: [TX_DEAL_TAG]
  })) as DeckObject | null;
  if (!pile) return null;
  let dealt: CardObject | null = null;
  try {
    dealt = await pile.dealTo({ seat });
  } catch (error) {
    dealt = null;
  }
  const left = await world.getObjectById(pile.id);
  if (left) left.destroy();
  return dealt ? dealt.id : null;
}

// --------------------------------------------------------------------------------- render --

async function txRenderHand(s: SvState, q: number): Promise<void> {
  const seat = txSeats[q];
  const real = !!txRealHand[seat];
  const want = s.hand[q].slice();
  const keep: TxEnt[] = [];
  for (const e of txHand[seat] || []) {
    if (want[e.r] > 0) {
      want[e.r] -= 1;
      keep.push(e);
    } else await txDestroy(e.id);
  }
  const showFaces = txPractice && q === 0;
  for (let r = 0; r < SV_RANKS; r += 1) {
    for (let k = 0; k < want[r]; k += 1) {
      const id = real ? await txDealToHand(seat, r) : await txSpawnCard(showFaces ? r : null, txSpawnPoint(), 0, !showFaces, showFaces ? String(txFace(r)) : "Card");
      if (id) keep.push({ id, r });
    }
  }
  txHand[seat] = keep;
  if (real) return;
  // A row on the table (practice): lowest value at the seat's left.
  const zone = txZones[seat] && txZones[seat]["HandZone"];
  if (!zone) return;
  keep.sort((a, b) => a.r - b.r);
  const n = keep.length;
  const step = n <= 1 ? 0 : Math.min(0.17, 1.35 / (n - 1));
  for (let i = 0; i < n; i += 1) {
    const h = await world.getObjectById(keep[i].id);
    if (!h) continue;
    h.unlock();
    h.setPosition(txLocal(zone, ((n - 1) * step) / 2 - i * step, 0, i * 0.0012));
    h.setRotation([0, txZoneYaw(zone), 0]);
    h.lock();
  }
}

async function txRenderSlots(s: SvState, q: number): Promise<void> {
  const seat = txSeats[q];
  const ups = txUp[seat] || (txUp[seat] = [null, null, null]);
  const downs = txDown[seat] || (txDown[seat] = [null, null, null]);
  for (let i = 0; i < 3; i += 1) {
    const zone = txZones[seat] && txZones[seat]["CardZone" + (i + 1)];
    if (!zone) continue;
    const yaw = txZoneYaw(zone);
    const d = s.down[q][i];
    const dEnt = downs[i];
    if (d < 0 && dEnt) {
      await txDestroy(dEnt.id);
      downs[i] = null;
    } else if (d >= 0 && !dEnt) {
      const id = await txSpawnCard(null, txLocal(zone, 0, 0, 0), yaw, true, "Face-down card");
      downs[i] = id ? { id, r: -1 } : null;
    }
    const u = s.up[q][i];
    const uEnt = ups[i];
    if (uEnt && uEnt.r !== u) {
      await txDestroy(uEnt.id);
      ups[i] = null;
    }
    if (u >= 0 && !ups[i]) {
      const id = await txSpawnCard(u, txLocal(zone, 0, TX_UP_SHIFT, 0.003), yaw, false, String(txFace(u)));
      ups[i] = id ? { id, r: u } : null;
    }
  }
}

function txLoosePos(i: number): { pos: Vec3; yaw: number } {
  const zone = txTableZone("PlayArea");
  const dx = 0.03 * Math.sin(i * 2.1);
  const dz = 0.03 * Math.cos(i * 1.3);
  return { pos: [zone.position[0] + dx, txSurface + 0.003 + (i + 1) * 0.0012, zone.position[2] + dz], yaw: 16 * Math.sin(i * 1.7) };
}

async function txRenderPile(s: SvState): Promise<void> {
  const pile = s.pile;
  const from = Math.max(0, pile.length - TX_PILE_LOOSE);
  // The stack under the loose cards.
  const baseKey = from > 0 ? pile.slice(0, from).join(",") : "";
  if (!txBase || txBase.key !== baseKey) {
    if (txBase) await txDestroy(txBase.id);
    txBase = null;
    if (from > 0) {
      const zone = txTableZone("PlayArea");
      const faces = pile.slice(0, from).reverse();
      const id = await txSpawnStack(faces, from, [zone.position[0], txSurface + 0.001, zone.position[2]], 0, false, "Pile");
      if (id) txBase = { id, key: baseKey };
    }
  }
  const next: { [index: number]: TxEnt } = {};
  for (const key of Object.keys(txLoose)) {
    const i = Number(key);
    const e = txLoose[i];
    if (i >= from && i < pile.length && pile[i] === e.r) next[i] = e;
    else await txDestroy(e.id);
  }
  for (let i = from; i < pile.length; i += 1) {
    if (next[i]) continue;
    const at = txLoosePos(i);
    const id = await txSpawnCard(pile[i], at.pos, at.yaw, false, String(txFace(pile[i])));
    if (id) next[i] = { id, r: pile[i] };
  }
  txLoose = next;
}

async function txRenderCount(current: { id: string; n: number } | null, n: number, zoneName: string, name: string): Promise<{ id: string; n: number } | null> {
  if (current && current.n === n) return current;
  if (current) await txDestroy(current.id);
  if (n <= 0) return null;
  const zone = txTableZone(zoneName);
  const id = await txSpawnStack(null, n, [zone.position[0], txSurface + 0.001, zone.position[2]], 0, true, name);
  return id ? { id, n } : null;
}

/** Make the table match the kernel state. */
async function txRender(): Promise<void> {
  const s = txState;
  if (!s) return;
  for (let q = 0; q < txSeats.length; q += 1) {
    await txRenderSlots(s, q);
    await txRenderHand(s, q);
  }
  await txRenderPile(s);
  txDrawPile = await txRenderCount(txDrawPile, s.draw.length, "Deck", "Draw pile");
  let out = 0;
  for (let r = 0; r < SV_RANKS; r += 1) out += s.burned[r];
  txOutPile = await txRenderCount(txOutPile, out, "Discard", "Out of the game");
  txRenderHud(s);
  txRenderHighlights(s);
}

// --------------------------------------------------------------------------------- HUD --

function txHudSet(key: string, value: UiValue, seat?: string, priv?: boolean): void {
  const k = (seat || "") + "|" + key + "|" + (priv ? "p" : "");
  if (k in txHudCache && txHudCache[k] === value) return;
  txHudCache[k] = value;
  if (seat) ui.set(key, value, seat, priv ? { private: true } : undefined);
  else ui.set(key, value);
}

function txDrawHud(): void {
  ui.show({
    id: "status",
    kind: "status",
    placement: { region: "upper" },
    theme: { icon: "playing_cards" },
    title: "{phase}",
    text: "{howToAll|}{seat.howTo|}",
    note: "{pileNote|}"
  });
  ui.show({
    id: "players",
    kind: "player-panel",
    counters: [
      { label: "Hand", value: "{seat.hand|0}", icon: "back_hand" },
      { label: "Face up", value: "{seat.up|0}", icon: "visibility" },
      { label: "Face down", value: "{seat.down|0}", icon: "visibility_off" }
    ]
  });
  ui.show({ id: "log", kind: "log", title: "Game log", placement: { region: "end" }, maxLines: 120 });
}

/** What the pile asks for, in words. */
function txToBeatText(s: SvState): string {
  if (s.again) return "start a new pile with any card";
  const t = svToBeat(s.pile);
  if (s.pile.length === 0) return "the pile is empty: any card";
  if (t < 0) return s.pile[s.pile.length - 1] === SV_TWO ? "a 2 reset the pile: any card" : "any card";
  const hidden = s.pile[s.pile.length - 1] === SV_SEVEN ? " (under the 7)" : "";
  return "beat a " + txFace(t) + hidden;
}

function txPhaseText(s: SvState): string {
  if (s.ph === SV_PH_OVER) return s.win === -2 ? "The game is a draw" : txSeatName(s.win) + " is out of cards and wins!";
  if (s.ph === SV_PH_CHOOSE) {
    const waiting: string[] = [];
    for (let q = 0; q < txSeats.length; q += 1) if (svSlots(s.up[q]) < 3) waiting.push(txSeatName(q));
    return "Choosing face-up cards: " + waiting.join(", ");
  }
  return txSeatName(s.who) + " to play - " + txToBeatText(s);
}

function txHowTo(s: SvState, q: number): string | null {
  if (s.ph === SV_PH_OVER) return null;
  if (s.ph === SV_PH_CHOOSE) {
    if (svSlots(s.up[q]) >= 3) return null;
    return txChoices[q] ? "Waiting for the others to choose." : "Pick the 3 cards to lay face up in the picker (usually 2s, 7s, 10s, then your highest).";
  }
  if (s.who !== q) return null;
  const legal = svLegalMoves(s);
  const src = svSource(s, q);
  const pickOnly = legal.length === 1 && legal[0] === SV_M_PICKUP;
  if (pickOnly) return "Nothing you hold can " + txToBeatText(s) + ". Pick up the pile: press the button, or click the pile.";
  if (src === 2) return "Turn over one of your face-down cards: click it. If it doesn't beat the pile, you pick the pile up.";
  const where = src === 1 ? "Your hand is empty: click one of your face-up cards" : txRealHand[txSeats[q]] ? "Click a card in your hand, or drag it onto the pile" : "Click a card in your row";
  return where + " to play it (" + txToBeatText(s) + "; 2, 7 and 10 can always be played). Or use the buttons.";
}

function txRenderHud(s: SvState): void {
  txHudSet("phase", txPhaseText(s));
  txHudSet("pileNote", "Pile " + s.pile.length + "  ·  Draw pile " + s.draw.length);
  for (let q = 0; q < txSeats.length; q += 1) {
    const seat = txSeats[q];
    txHudSet("hand", svSum(s.hand[q]), seat);
    txHudSet("up", svSlots(s.up[q]), seat);
    txHudSet("down", svSlots(s.down[q]), seat);
    const how = txHumanSeat(q) ? txHowTo(s, q) : null;
    if (txPractice) {
      if (q === 0) txHudSet("howToAll", how);
    } else txHudSet("howTo", how, seat, true);
  }
  if (s.ph === SV_PH_OVER) world.setTurn(null);
  else if (s.ph === SV_PH_CHOOSE) {
    const choosing: string[] = [];
    for (let q = 0; q < txSeats.length; q += 1) if (svSlots(s.up[q]) < 3) choosing.push(txSeats[q]);
    world.setTurn(choosing);
  } else world.setTurn(txSeats[s.who]);
  txRenderMoves(s);
}

/** A HUD button's label for a move. */
function txMoveLabel(s: SvState, m: number): string {
  if (m === SV_M_PICKUP) return "Pick up the pile (" + s.pile.length + ")";
  if (m >= SV_M_BLIND && m < SV_M_BLIND + 3) return "Turn over face-down card " + (m - SV_M_BLIND + 1);
  if (m >= SV_M_PLAY && m < SV_M_BLIND) {
    const r = Math.floor((m - SV_M_PLAY) / SV_MAX_COUNT);
    const k = ((m - SV_M_PLAY) % SV_MAX_COUNT) + 1;
    return "Play " + txCards(r, k);
  }
  return "Lay " + txCards(m - SV_M_CHOOSE, 1) + " face up";
}

function txAudience(q: number): UiAudience {
  return txPractice ? { scope: "all" } : { scope: "seats", seats: [txSeats[q]] };
}

/** The mover's buttons: every legal move, while a person is to play. */
function txRenderMoves(s: SvState): void {
  const q = s.who;
  if (s.ph !== SV_PH_PLAY || !txHumanSeat(q) || txOver) {
    ui.hide(["s7210-moves", "s7210-count"]);
    return;
  }
  const legal = svLegalMoves(s);
  const shown = legal.filter((m) => !(m >= SV_M_BLIND + 1 && m < SV_M_BLIND + 3)).slice(0, 16);
  ui.show({
    id: "s7210-moves",
    kind: "actions",
    placement: { region: "lower" },
    audience: txAudience(q),
    title: "Your move",
    actions: shown.map((m) => ({
      id: "m" + m,
      label: m >= SV_M_BLIND && m < SV_M_BLIND + 3 ? "Turn over a face-down card" : txMoveLabel(s, m),
      icon: m === SV_M_PICKUP ? "back_hand" : m >= SV_M_BLIND ? "flip" : "playing_cards",
      tone: m === SV_M_PICKUP ? ("warning" as UiTone) : ("accent" as UiTone)
    }))
  });
}

/** Outline what the mover may play, privately. */
function txRenderHighlights(s: SvState): void {
  const ids: string[] = [];
  const q = s.who;
  if (s.ph === SV_PH_PLAY && txHumanSeat(q) && !txOver) {
    const seat = txSeats[q];
    const legal = svLegalMoves(s);
    const src = svSource(s, q);
    if (src === 0) for (const e of txHand[seat] || []) if (legal.indexOf(svPlayMove(e.r, 1)) >= 0) ids.push(e.id);
    if (src === 1) for (const e of txUp[seat] || []) if (e && legal.indexOf(svPlayMove(e.r, 1)) >= 0) ids.push(e.id);
    if (src === 2) for (const e of txDown[seat] || []) if (e) ids.push(e.id);
    if (legal.length === 1 && legal[0] === SV_M_PICKUP) {
      for (const key of Object.keys(txLoose)) ids.push(txLoose[Number(key)].id);
      if (txBase) ids.push(txBase.id);
    }
  }
  const key = (txPractice ? "all" : String(q)) + ":" + ids.join(",");
  if (key === txLastHighlight) return;
  txLastHighlight = key;
  world.clearHighlights();
  if (ids.length > 0) world.setHighlight(ids, "playable", txPractice ? undefined : { seats: [txSeats[q]] });
}

// --------------------------------------------------------------------------------- log --

function txLogMove(s: SvState): void {
  const e = s.last;
  if (!e) return;
  const who = txSeatName(e.p);
  const seat = txSeats[e.p];
  let text = "";
  switch (e.k) {
    case "start":
      text = who + " turns over " + txCards(e.r, 1) + " to start the pile" + (e.burn ? ": a 10 - it explodes at once, so any card starts it." : ".");
      break;
    case "choose": {
      if (svSlots(s.up[e.p]) < 3) return;
      text = who + " lays " + s.up[e.p].map((u) => String(txFace(u))).join(", ") + " face up.";
      break;
    }
    case "play":
    case "blind": {
      const lead = e.k === "blind" ? who + " turns over " + txCards(e.r, 1) + " and plays it" : who + " plays " + txCards(e.r, e.n) + (e.from === "up" ? " from the face-up cards" : "");
      let tail = ".";
      if (e.burn) tail = e.r === SV_TEN ? " - the pile explodes!" : " - four of a kind clears the pile!";
      else if (e.r === SV_TWO) tail = " - reset.";
      else if (e.r === SV_SEVEN) tail = " - invisible.";
      text = lead + tail + (e.again ? " " + who + " plays again." : "");
      break;
    }
    case "fail":
      text = who + " turns over " + txCards(e.r, 1) + ", which doesn't beat the pile, and picks up " + e.n + " cards.";
      break;
    case "pickup":
      text = who + " can't play and picks up the pile (" + e.n + " cards).";
      break;
    default:
      return;
  }
  ui.log(text, { seat });
}

// --------------------------------------------------------------------------------- moves --

/** Apply one move (from a person or a bot), record it, log it. */
function txApply(m: number): void {
  if (!txState) return;
  txState = kernel.apply(txState, m);
  txLogMove(txState);
  if (txRecording) {
    try {
      match.move(m);
    } catch (error) {
      txRecording = false;
      world.log("Seven, Twos & Tens: the match stopped recording (" + txDescribe(error) + ").");
    }
  }
}

type TxChooser = (s: SvState, difficulty: string | null, signal: BotAbortSignal | undefined) => Promise<number>;

async function txAiMove(s: SvState, difficulty: string | null, signal: BotAbortSignal | undefined): Promise<number> {
  const level = TX_AI_LEVELS[difficulty || "normal"] || TX_AI_LEVELS["normal"];
  const legal = svLegalMoves(s);
  if (legal.length === 1) return legal[0];
  const votes: number[] = legal.map(() => 0);
  try {
    for (let d = 0; d < level.dets; d += 1) {
      const det = svDeterminize(s, s.who, Math.random);
      const res = await ai.mcts({ kernel, modelId: level.modelId, state: det, simulations: Math.max(1, Math.round(level.sims / level.dets)), temperature: level.temperature, playerCount: s.seats.length, signal });
      for (let i = 0; i < legal.length; i += 1) votes[i] += res.policy[legal[i]] || 0;
      if (level.dets === 1 && legal.indexOf(res.move) >= 0) return res.move;
    }
  } catch (error) {
    return svPimcMove(s, TX_SHARK_WORLDS["normal"], Math.random);
  }
  let best = 0;
  for (let i = 1; i < legal.length; i += 1) if (votes[i] > votes[best]) best = i;
  return votes[best] > 0 ? legal[best] : svPimcMove(s, TX_SHARK_WORLDS["normal"], Math.random);
}

const TX_CHOOSERS: { [botId: string]: TxChooser } = {
  greedy: async (s) => svGreedyMove(s),
  "card-shark": async (s, difficulty) => svPimcMove(s, TX_SHARK_WORLDS[difficulty || "normal"] || 16, Math.random),
  "seven-ai": async (s, difficulty, signal) => txAiMove(s, difficulty, signal)
};

function txBotOf(q: number): { chooser: TxChooser; difficulty: string | null } {
  if (txPractice) return { chooser: TX_CHOOSERS["card-shark"], difficulty: "normal" };
  if (txGone[q]) return { chooser: TX_CHOOSERS["greedy"], difficulty: null };
  const p = world.getPlayers().find((x) => x.seat === txSeats[q] && x.isBot);
  const chooser = p && p.botId && TX_CHOOSERS[p.botId] ? TX_CHOOSERS[p.botId] : TX_CHOOSERS["card-shark"];
  return { chooser, difficulty: p ? p.difficultyId : null };
}

/**
 * Play everything that does not wait for a person: bots' moves, and people's face-up picks once the
 * kernel reaches their seat. Stops when a person must move or the game ends.
 */
async function txAdvance(signal?: BotAbortSignal): Promise<void> {
  for (let guard = 0; guard < 4000; guard += 1) {
    const s = txState;
    if (!s || s.ph === SV_PH_OVER || txOver) break;
    const q = s.who;
    let m = -1;
    if (txIsBotSeat(q)) {
      if (signal && signal.aborted) return;
      const bot = txBotOf(q);
      const legal = svLegalMoves(s);
      try {
        m = await bot.chooser(s, bot.difficulty, signal);
      } catch (error) {
        m = svGreedyMove(s);
      }
      if (txState !== s) return;
      if (legal.indexOf(m) < 0) m = svGreedyMove(s);
    } else if (s.ph === SV_PH_CHOOSE && txChoices[q] && txChoices[q].length > 0) {
      const r = txChoices[q].shift() as number;
      m = SV_M_CHOOSE + r;
      if (svLegalMoves(s).indexOf(m) < 0) m = svGreedyMove(s);
    } else break;
    const wasPlay = s.ph === SV_PH_PLAY;
    txApply(m);
    if (wasPlay || (txState && txState.ph === SV_PH_PLAY && s.ph === SV_PH_CHOOSE)) {
      await txRender();
      if (txState && txState.ph !== SV_PH_OVER && txIsBotSeat(txState.who)) await world.wait(TX_BOT_PACE);
    }
  }
  await txAfterMoves();
}

async function txAfterMoves(): Promise<void> {
  if (!txState) return;
  await txRender();
  if (txState.ph === SV_PH_CHOOSE) txOpenChooseWindows();
  if (txState.ph === SV_PH_OVER && !txOver) await txGameOver();
}

/** A person's move: check it is theirs and legal, play it, then everything that follows. */
async function txHumanMove(q: number, m: number): Promise<void> {
  const s = txState;
  if (!s || txOver || s.ph !== SV_PH_PLAY) return;
  if (q !== s.who || txIsBotSeat(q)) {
    txHint(q, "It is " + txSeatName(s.who) + "'s move.");
    return;
  }
  if (svLegalMoves(s).indexOf(m) < 0) {
    txHint(q, "That move isn't allowed now: " + txToBeatText(s) + ".");
    return;
  }
  txHumanMoved = true;
  ui.hide("s7210-count");
  txApply(m);
  await txRender();
  if (txState && txState.ph !== SV_PH_OVER && txIsBotSeat(txState.who)) await world.wait(TX_BOT_PACE * 0.6);
  await txAdvance();
}

function txHint(q: number, text: string): void {
  if (q < 0) return;
  ui.toast(text, { tone: "warning", icon: "info", to: txAudience(q) });
}

/** A card of rank `r` was picked (clicked, or dropped on the pile) by seat `q` from hand or face-up cards. */
function txOfferPlays(q: number, r: number): void {
  const s = txState;
  if (!s || s.ph !== SV_PH_PLAY) return;
  if (s.who !== q) {
    txHint(q, "It is " + txSeatName(s.who) + "'s move.");
    return;
  }
  const legal = svLegalMoves(s);
  const plays: number[] = [];
  for (let k = 1; k <= SV_MAX_COUNT; k += 1) if (legal.indexOf(svPlayMove(r, k)) >= 0) plays.push(svPlayMove(r, k));
  if (plays.length === 0) {
    const src = svSource(s, q);
    if (legal.length === 1 && legal[0] === SV_M_PICKUP) txHint(q, "Nothing you hold can " + txToBeatText(s) + ": pick up the pile.");
    else if (src === 1 && s.hand[q][r] === 0 && svUpCount(s, q, r) === 0) txHint(q, "Play your face-up cards now.");
    else txHint(q, "A " + txFace(r) + " can't " + txToBeatText(s) + ".");
    return;
  }
  if (plays.length === 1) {
    void txRun(() => txHumanMove(q, plays[0]));
    return;
  }
  ui.show({
    id: "s7210-count",
    kind: "prompt",
    audience: txAudience(q),
    title: "How many " + txFace(r) + "s?",
    body: plays.length >= 4 ? "Four or more of a kind clears the pile." : "Play them together, or keep some back.",
    actions: plays.map((m) => ({ id: "m" + m, label: txMoveLabel(s, m), icon: "playing_cards" })).concat([{ id: "cancel", label: "Cancel", icon: "close" }]),
    dismissible: true,
    timing: { until: "action" }
  });
}

// --------------------------------------------------------------------------------- choosing --

/** Each person still choosing gets a private picker with their six cards. */
function txOpenChooseWindows(): void {
  const s = txState;
  if (!s || s.ph !== SV_PH_CHOOSE) return;
  for (let q = 0; q < txSeats.length; q += 1) {
    const seat = txSeats[q];
    if (!txHumanSeat(q) || txChoices[q] || txChoosing[seat] || svSlots(s.up[q]) > 0) continue;
    const cards = (txHand[seat] || []).slice().sort((a, b) => b.r - a.r);
    if (cards.length === 0) continue;
    txChoosing[seat] = true;
    ui.show({
      id: "s7210-choose-" + seat,
      kind: "choice",
      placement: { region: "sheet" },
      audience: txAudience(q),
      title: "Choose your 3 face-up cards",
      body: "They lie face up on your face-down cards and are played once your hand is empty. Most players lay down 2s, 7s and 10s, then their highest cards.",
      choices: {
        options: cards.map((e, i) => ({ id: "c" + i + "-" + e.r, label: String(txFace(e.r)), entityId: e.id })),
        min: 3,
        max: 3,
        confirm: { id: "ok", label: "Lay them face up", icon: "check" }
      }
    });
  }
}

function txTakeChoice(q: number, picks: readonly string[]): void {
  const s = txState;
  if (!s || s.ph !== SV_PH_CHOOSE || txChoices[q]) return;
  const ranks: number[] = [];
  const left = s.hand[q].slice();
  for (const id of picks) {
    const r = Number(id.split("-")[1]);
    if (r >= 0 && r < SV_RANKS && left[r] > 0) {
      left[r] -= 1;
      ranks.push(r);
    }
  }
  if (ranks.length !== 3) {
    txHint(q, "Pick exactly three cards.");
    txChoosing[txSeats[q]] = false;
    txOpenChooseWindows();
    return;
  }
  txChoices[q] = ranks;
  ui.hide("s7210-choose-" + txSeats[q]);
  txHumanMoved = true;
  void txRun(async () => {
    if (txState) txRenderHud(txState);
    await txAdvance();
  });
}

// --------------------------------------------------------------------------------- game --

async function txClearTable(): Promise<void> {
  world.clearHighlights();
  txLastHighlight = "";
  ui.hide(["s7210-moves", "s7210-count", "s7210-result", "s7210-game"]);
  for (const seat of TX_SEAT_ORDER) ui.hide("s7210-choose-" + seat);
  // In the Scripted variant every card on the table is the script's: the pack's own deck, cards dealt into hands, leftovers.
  for (const kind of ["card", "deck"] as const) for (const h of await world.getAllObjects({ kind })) h.destroy();
  for (const h of await world.getAllObjects({ tag: TX_TAG })) h.destroy();
  for (const seat of Object.keys(txHand)) delete txHand[seat];
  for (const seat of Object.keys(txUp)) delete txUp[seat];
  for (const seat of Object.keys(txDown)) delete txDown[seat];
  for (const seat of Object.keys(txChoosing)) delete txChoosing[seat];
  for (const k of Object.keys(txChoices)) delete txChoices[Number(k)];
  for (const k of Object.keys(txGone)) delete txGone[Number(k)];
  txLoose = {};
  txBase = null;
  txDrawPile = null;
  txOutPile = null;
}

async function txStartMatch(setup: SvSetup): Promise<void> {
  txRecording = false;
  if (typeof match === "undefined") return;
  const running = match.current();
  if (running && (running.status === "live" || running.status === "opening")) {
    try {
      await match.abort("new game");
    } catch (error) {
      world.log("Seven, Twos & Tens: could not stop the previous match (" + txDescribe(error) + ").");
    }
  }
  if (txPractice) return;
  try {
    const info = await (match.start as unknown as TxMatchStart)({ kernel, setup, seats: txSeats });
    txRecording = !!info && info.status === "live";
  } catch (error) {
    world.log("Seven, Twos & Tens: this game is not recorded as a match (" + txDescribe(error) + ").");
  }
}

async function txNewGame(): Promise<void> {
  txStarting = true;
  try {
    txOver = false;
    txHumanMoved = false;
    txChooseSeats();
    txDrawHud();
    if (!(await txLoadZones())) {
      txHudSet("phase", "Seven, Twos & Tens cannot start");
      txHudSet("howToAll", "The table has no card zones for these seats.");
      return;
    }
    txHudSet("phase", "Dealing a new game");
    for (const k of Object.keys(txHudCache)) delete txHudCache[k];
    await txClearTable();
    const setup: SvSetup = { seed: Math.floor(Math.random() * 2147483647), first: Math.floor(Math.random() * txSeats.length), decks: txSeats.length >= 5 ? 2 : 1 };
    txSetup = setup;
    await txStartMatch(setup);
    txState = kernel.initial(txSeats, setup);
    world.setGameOver(null);
    const names = txSeats.map((_, q) => txSeatName(q)).join(", ");
    const intro = "New game: " + names + (setup.decks === 2 ? " (two decks)" : "") + ". " + txSeatName(setup.first || 0) + " goes first." + (txPractice ? " Practice: you play against a bot." : "");
    ui.log(intro, { tone: "info" });
    txShowGameControls();
    ui.toast(intro, { tone: "info", icon: "playing_cards", seconds: 6 });
    await txRender();
    await txAdvance();
  } finally {
    txStarting = false;
  }
}

/** After a reload: rebuild the game from the running match (setup + recorded moves). */
async function txResume(): Promise<boolean> {
  if (typeof match === "undefined") return false;
  const info = match.current();
  if (!info || info.status !== "live") return false;
  const setup = match.setup() as SvSetup | undefined;
  if (!setup || typeof setup.seed !== "number") return false;
  try {
    const again = await (match.start as unknown as TxMatchStart)({ kernel });
    if (!again || again.id !== info.id) return false;
  } catch (error) {
    return false;
  }
  txSeats = info.participants.map((p) => p.seat);
  txPractice = false;
  if (!(await txLoadZones())) return false;
  txDrawHud();
  await txClearTable();
  txSetup = setup;
  let s = kernel.initial(txSeats, setup);
  for (const m of match.moves()) s = kernel.apply(s, m as number);
  txState = s;
  txRecording = true;
  txHumanMoved = true;
  ui.log("The running game was picked back up (" + match.moves().length + " moves).", { tone: "info" });
  await txRender();
  await txAdvance();
  return true;
}

/** Practice controls: a new deal at any time, and a bot for the person's seat. */
function txShowGameControls(): void {
  if (!txPractice) {
    ui.hide("s7210-game");
    return;
  }
  ui.show({
    id: "s7210-game",
    kind: "actions",
    placement: { region: "lower-end", devices: { phone: { menu: true } } },
    actions: [
      { id: "new", label: "New game", icon: "replay" },
      { id: "auto", label: txAutoplay ? "I'll play my cards" : "Let a bot play my cards", icon: txAutoplay ? "person" : "smart_toy" }
    ]
  });
}

async function txGameOver(): Promise<void> {
  const s = txState;
  if (!s || s.ph !== SV_PH_OVER) return;
  txOver = true;
  world.clearHighlights();
  txLastHighlight = "";
  ui.hide(["s7210-moves", "s7210-count"]);
  const result = s.win === -2 ? { draw: true as const } : { winner: txSeats[s.win] };
  const headline = s.win === -2 ? "The game is a draw." : txSeatName(s.win) + " is out of cards and wins!";
  const scores: Record<string, number> = {};
  for (let q = 0; q < txSeats.length; q += 1) scores[txSeats[q]] = svCardsLeft(s, q);
  ui.show({
    id: "s7210-result",
    kind: "result",
    headline,
    lines: txSeats.map((seat, q) => txSeatName(q) + ": " + scores[seat] + " card" + (scores[seat] === 1 ? "" : "s") + " left")
