/** What one of the script's entities is: a hand card, a face-up or face-down slot, or the pile. */
function txFind(id: string): { kind: string; q: number; r: number; slot: number } | null {
  for (let q = 0; q < txSeats.length; q += 1) {
    const seat = txSeats[q];
    for (const e of txHand[seat] || []) if (e.id === id) return { kind: "hand", q, r: e.r, slot: -1 };
    const ups = txUp[seat] || [];
    for (let i = 0; i < ups.length; i += 1) if (ups[i] && (ups[i] as TxEnt).id === id) return { kind: "up", q, r: (ups[i] as TxEnt).r, slot: i };
    const downs = txDown[seat] || [];
    for (let i = 0; i < downs.length; i += 1) if (downs[i] && (downs[i] as TxEnt).id === id) return { kind: "down", q, r: -1, slot: i };
