  if (!what) return;
  const q = txSeatOf(context.seat, context.actor);
  if (q < 0) return;
  if (s.ph === SV_PH_CHOOSE) {
    if (what.kind === "hand" && what.q === q) txHint(q, "Pick your face-up cards in the picker.");
