ui.onAction.add((event) => {
  const s = txState;
  if (!s) return;
  if (event.widgetId === "s7210-game" && event.actionId === "new") {
    if (!txOver && !txPractice) return;
    void txRun(() => txNewGame());
    return;
  }
  if (event.widgetId === "s7210-game" && event.actionId === "auto" && txPractice) {
    txAutoplay = !txAutoplay;
    txShowGameControls();
