      if (txState) await txRender();
      await txAdvance();
    });
    return;
  }
  const q = txSeatOf(event.seat, event.peerId);
  if (event.widgetId.indexOf("s7210-choose-") === 0) {
    const seat = event.widgetId.slice("s7210-choose-".length);
    const owner = txSeats.indexOf(seat);
    if (owner < 0 || (q !== owner && !txPractice) || event.dismissed) return;
    if (event.actionId === "ok" && event.value) txTakeChoice(owner, event.value);
    return;
  }
  if (event.widgetId === "s7210-moves" || event.widgetId === "s7210-count") {
    if (!event.actionId || event.actionId === "cancel") {
      ui.hide("s7210-count");
      return;
    }
    const m = Number(event.actionId.slice(1));
    if (!isFinite(m)) return;
    if (m >= SV_M_BLIND && m < SV_M_BLIND + 3) {
      // "Turn over a face-down card": the first one left.
      const slot = s.down[s.who].findIndex((d) => d >= 0);
      void txRun(() => txHumanMove(q, SV_M_BLIND + Math.max(0, slot)));
    } else void txRun(() => txHumanMove(q, m));
  }
});

