      return;
    }
    void txRun(() => txNewGame());
  });
}

function txBotTurn(ctx: BotTurnContext): Promise<void> {
  return txRun(() => txAdvance(ctx.signal));
}

// One literal registration per bot: the editor reads the handler ids out of these calls.
bots.register({ id: "greedy", onTurn: (ctx) => txBotTurn(ctx) });
bots.register({ id: "card-shark", onTurn: (ctx) => txBotTurn(ctx) });
bots.register({ id: "seven-ai", onTurn: (ctx) => txBotTurn(ctx) });

if (typeof match !== "undefined") {
  match.onForfeit.add((participant) => {
    void txRun(async () => {
      const s = txState;
      if (!s || s.ph === SV_PH_OVER) return;
      const q = txSeats.indexOf(participant.seat);
      if (q < 0) return;
      ui.log(txSeatName(q) + " forfeits.", { tone: "warning" });
      if (txSeats.length === 2) {
        // The platform records the forfeit; the board just shows it.
        txRecording = false;
        txState = { ...s, ph: SV_PH_OVER, win: 1 - q };
        await txAfterMoves();
        return;
      }
      ui.log("The table plays " + txSeatName(q) + "'s cards from now on.", { tone: "info" });
      txGone[q] = true;
      await txAdvance();
    });
  });
  match.onTakeback.add(() => {
    void txRun(async () => {
      if (!txSetup) return;
      let s = kernel.initial(txSeats, txSetup);
      for (const m of match.moves()) s = kernel.apply(s, m as number);
      txState = s;
      txOver = false;
      await txRender();
      await txAdvance();
    });
  });
}

void txRun(async () => {
  const variant = world.getVariant();
  if (variant.id !== null && !variant.rulesEnforced) return;
  if (await txResume()) return;
  await world.wait(0.5);
  await txNewGame();
});

