/** A HUD button's label for a move. */
function txMoveLabel(s, m) {
    if (m === SV_M_PICKUP)
        return "Pick up the pile (" + s.pile.length + ")";
    if (m >= SV_M_BLIND && m < SV_M_BLIND + 3)
        return "Turn over face-down card " + (m - SV_M_BLIND + 1);
    if (m >= SV_M_PLAY && m < SV_M_BLIND) {
        const r = Math.floor((m - SV_M_PLAY) / SV_MAX_COUNT);
        const k = ((m - SV_M_PLAY) % SV_MAX_COUNT) + 1;
        return "Play " + txCards(r, k);
    }
    return "Lay " + txCards(m - SV_M_CHOOSE, 1) + " face up";
}
function txAudience(q) {
    return txPractice ? { scope: "all" } : { scope: "seats", seats: [txSeats[q]] };
}
/** The mover's buttons: every legal move, while a person is to play. */
function txRenderMoves(s) {
    const q = s.who;
    if (s.ph !== SV_PH_PLAY || !txHumanSeat(q) || txOver) {
        ui.hide(["s7210-moves", "s7210-count"]);
        return;
    }
    const legal = svLegalMoves(s);
    const shown = legal.filter((m) => !(m >= SV_M_BLIND + 1 && m < SV_M_BLIND + 3)).slice(0, 16);
    ui.show({
        id: "s7210-moves",
        kind: "actions",
        placement: { region: "lower" },
        audience: txAudience(q),
        title: "Your move",
        actions: shown.map((m) => ({
            id: "m" + m,
            label: m >= SV_M_BLIND && m < SV_M_BLIND + 3 ? "Turn over a face-down card" : txMoveLabel(s, m),
            icon: m === SV_M_PICKUP ? "back_hand" : m >= SV_M_BLIND ? "flip" : "playing_cards",
            tone: m === SV_M_PICKUP ? "warning" : "accent"
        }))
    });
}
/** Outline what the mover may play, privately. */
function txRenderHighlights(s) {
    const ids = [];
    const q = s.who;
    if (s.ph === SV_PH_PLAY && txHumanSeat(q) && !txOver) {
        const seat = txSeats[q];
        const legal = svLegalMoves(s);
        const src = svSource(s, q);
        if (src === 0)
            for (const e of txHand[seat] || [])
                if (legal.indexOf(svPlayMove(e.r, 1)) >= 0)
                    ids.push(e.id);
        if (src === 1)
            for (const e of txUp[seat] || [])
                if (e && legal.indexOf(svPlayMove(e.r, 1)) >= 0)
                    ids.push(e.id);
        if (src === 2)
            for (const e of txDown[seat] || [])
                if (e)
                    ids.push(e.id);
        if (legal.length === 1 && legal[0] === SV_M_PICKUP) {
            for (const key of Object.keys(txLoose))
                ids.push(txLoose[Number(key)].id);
            if (txBase)
                ids.push(txBase.id);
        }
    }
    const key = (txPractice ? "all" : String(q)) + ":" + ids.join(",");
    if (key === txLastHighlight)
        return;
    txLastHighlight = key;
    world.clearHighlights();
    if (ids.length > 0)
        world.setHighlight(ids, "playable", txPractice ? undefined : { seats: [txSeats[q]] });
}
// --------------------------------------------------------------------------------- log --
function txLogMove(s) {
    const e = s.last;
    if (!e)
        return;
    const who = txSeatName(e.p);
    const seat = txSeats[e.p];
    let text = "";
    switch (e.k) {
        case "start":
            text = who + " turns over " + txCards(e.r, 1) + " to start the pile" + (e.burn ? ": a 10 - it explodes at once, so any card starts it." : ".");
            break;
        case "choose": {
            if (svSlots(s.up[e.p]) < 3)
                return;
            text = who + " lays " + s.up[e.p].map((u) => String(txFace(u))).join(", ") + " face up.";
            break;
        }
        case "play":
        case "blind": {
            const lead = e.k === "blind" ? who + " turns over " + txCards(e.r, 1) + " and plays it" : who + " plays " + txCards(e.r, e.n) + (e.from === "up" ? " from the face-up cards" : "");
            let tail = ".";
            if (e.burn)
                tail = e.r === SV_TEN ? " - the pile explodes!" : " - four of a kind clears the pile!";
            else if (e.r === SV_TWO)
                tail = " - reset.";
            else if (e.r === SV_SEVEN)
                tail = " - invisible.";
            text = lead + tail + (e.again ? " " + who + " plays again." : "");
            break;
        }
        case "fail":
            text = who + " turns over " + txCards(e.r, 1) + ", which doesn't beat the pile, and picks up " + e.n + " cards.";
            break;
        case "pickup":
            text = who + " can't play and picks up the pile (" + e.n + " cards).";
            break;
        default:
            return;
    }
    ui.log(text, { seat });
}
// --------------------------------------------------------------------------------- moves --
/** Apply one move (from a person or a bot), record it, log it. */
function txApply(m) {
    if (!txState)
        return;
    txState = kernel.apply(txState, m);
    txLogMove(txState);
    if (txRecording) {
        try {
            match.move(m);
        }
        catch (error) {
            txRecording = false;
            world.log("Seven, Twos & Tens: the match stopped recording (" + txDescribe(error) + ").");
        }
    }
}
async function txAiMove(s, difficulty, signal) {
    const level = TX_AI_LEVELS[difficulty || "normal"] || TX_AI_LEVELS["normal"];
    const legal = svLegalMoves(s);
    if (legal.length === 1)
        return legal[0];
    const votes = legal.map(() => 0);
    try {
        for (let d = 0; d < level.dets; d += 1) {
            const det = svDeterminize(s, s.who, Math.random);
            const res = await ai.mcts({ kernel, modelId: level.modelId, state: det, simulations: Math.max(1, Math.round(level.sims / level.dets)), temperature: level.temperature, playerCount: s.seats.length, signal });
            for (let i = 0; i < legal.length; i += 1)
                votes[i] += res.policy[legal[i]] || 0;
            if (level.dets === 1 && legal.indexOf(res.move) >= 0)
                return res.move;
        }
    }
    catch (error) {
        return svPimcMove(s, TX_SHARK_WORLDS["normal"], Math.random);
    }
    let best = 0;
    for (let i = 1; i < legal.length; i += 1)
        if (votes[i] > votes[best])
            best = i;
    return votes[best] > 0 ? legal[best] : svPimcMove(s, TX_SHARK_WORLDS["normal"], Math.random);
}
const TX_CHOOSERS = {
    greedy: async (s) => svGreedyMove(s),
    "card-shark": async (s, difficulty) => svPimcMove(s, TX_SHARK_WORLDS[difficulty || "normal"] || 16, Math.random),
    "seven-ai": async (s, difficulty, signal) => txAiMove(s, difficulty, signal)
};
function txBotOf(q) {
    if (txPractice)
        return { chooser: TX_CHOOSERS["card-shark"], difficulty: "normal" };
    if (txGone[q])
        return { chooser: TX_CHOOSERS["greedy"], difficulty: null };
    const p = world.getPlayers().find((x) => x.seat === txSeats[q] && x.isBot);
    const chooser = p && p.botId && TX_CHOOSERS[p.botId] ? TX_CHOOSERS[p.botId] : TX_CHOOSERS["card-shark"];
    return { chooser, difficulty: p ? p.difficultyId : null };
}
/**
 * Play everything that does not wait for a person: bots' moves, and people's face-up picks once the
 * kernel reaches their seat. Stops when a person must move or the game ends.
 */
async function txAdvance(signal) {
    for (let guard = 0; guard < 4000; guard += 1) {
        const s = txState;
        if (!s || s.ph === SV_PH_OVER || txOver)
            break;
        const q = s.who;
        let m = -1;
        if (txIsBotSeat(q)) {
            if (signal && signal.aborted)
                return;
            const bot = txBotOf(q);
            const legal = svLegalMoves(s);
            try {
                m = await bot.chooser(s, bot.difficulty, signal);
            }
            catch (error) {
                m = svGreedyMove(s);
            }
            if (txState !== s)
                return;
            if (legal.indexOf(m) < 0)
                m = svGreedyMove(s);
        }
        else if (s.ph === SV_PH_CHOOSE && txChoices[q] && txChoices[q].length > 0) {
            const r = txChoices[q].shift();
            m = SV_M_CHOOSE + r;
            if (svLegalMoves(s).indexOf(m) < 0)
                m = svGreedyMove(s);
        }
        else
            break;
        const wasPlay = s.ph === SV_PH_PLAY;
        txApply(m);
        if (wasPlay || (txState && txState.ph === SV_PH_PLAY && s.ph === SV_PH_CHOOSE)) {
            await txRender();
            if (txState && txState.ph !== SV_PH_OVER && txIsBotSeat(txState.who))
                await world.wait(TX_BOT_PACE);
        }
    }
    await txAfterMoves();
}
async function txAfterMoves() {
    if (!txState)
        return;
    await txRender();
    if (txState.ph === SV_PH_CHOOSE)
        txOpenChooseWindows();
    if (txState.ph === SV_PH_OVER && !txOver)
        await txGameOver();
}
/** A person's move: check it is theirs and legal, play it, then everything that follows. */
async function txHumanMove(q, m) {
    const s = txState;
    if (!s || txOver || s.ph !== SV_PH_PLAY)
        return;
    if (q !== s.who || txIsBotSeat(q)) {
        txHint(q, "It is " + txSeatName(s.who) + "'s move.");
        return;
    }
    if (svLegalMoves(s).indexOf(m) < 0) {
        txHint(q, "That move isn't allowed now: " + txToBeatText(s) + ".");
        return;
    }
    txHumanMoved = true;
    ui.hide("s7210-count");
    txApply(m);
    await txRender();
    if (txState && txState.ph !== SV_PH_OVER && txIsBotSeat(txState.who))
        await world.wait(TX_BOT_PACE * 0.6);
    await txAdvance();
}
function txHint(q, text) {
    if (q < 0)
        return;
    ui.toast(text, { tone: "warning", icon: "info", to: txAudience(q) });
}
/** A card of rank `r` was picked (clicked, or dropped on the pile) by seat `q` from hand or face-up cards. */
function txOfferPlays(q, r) {
    const s = txState;
    if (!s || s.ph !== SV_PH_PLAY)
        return;
    if (s.who !== q) {
        txHint(q, "It is " + txSeatName(s.who) + "'s move.");
        return;
    }
    const legal = svLegalMoves(s);
    const plays = [];
    for (let k = 1; k <= SV_MAX_COUNT; k += 1)
        if (legal.indexOf(svPlayMove(r, k)) >= 0)
            plays.push(svPlayMove(r, k));
    if (plays.length === 0) {
        const src = svSource(s, q);
        if (legal.length === 1 && legal[0] === SV_M_PICKUP)
            txHint(q, "Nothing you hold can " + txToBeatText(s) + ": pick up the pile.");
        else if (src === 1 && s.hand[q][r] === 0 && svUpCount(s, q, r) === 0)
            txHint(q, "Play your face-up cards now.");
        else
            txHint(q, "A " + txFace(r) + " can't " + txToBeatText(s) + ".");
        return;
    }
    if (plays.length === 1) {
        void txRun(() => txHumanMove(q, plays[0]));
        return;
    }
    ui.show({
        id: "s7210-count",
        kind: "prompt",
        audience: txAudience(q),
        title: "How many " + txFace(r) + "s?",
        body: plays.length >= 4 ? "Four or more of a kind clears the pile." : "Play them together, or keep some back.",
        actions: plays.map((m) => ({ id: "m" + m, label: txMoveLabel(s, m), icon: "playing_cards" })).concat([{ id: "cancel", label: "Cancel", icon: "close" }]),
        dismissible: true,
        timing: { until: "action" }
    });
}
// --------------------------------------------------------------------------------- choosing --
/** Each person still choosing gets a private picker with their six cards. */
function txOpenChooseWindows() {
    const s = txState;
    if (!s || s.ph !== SV_PH_CHOOSE)
        return;
    for (let q = 0; q < txSeats.length; q += 1) {
        const seat = txSeats[q];
        if (!txHumanSeat(q) || txChoices[q] || txChoosing[seat] || svSlots(s.up[q]) > 0)
            continue;
        const cards = (txHand[seat] || []).slice().sort((a, b) => b.r - a.r);
        if (cards.length === 0)
            continue;
        txChoosing[seat] = true;
        ui.show({
            id: "s7210-choose-" + seat,
            kind: "choice",
            placement: { region: "sheet" },
            audience: txAudience(q),
            title: "Choose your 3 face-up cards",
            body: "They lie face up on your face-down cards and are played once your hand is empty. Most players lay down 2s, 7s and 10s, then their highest cards.",
            choices: {
                options: cards.map((e, i) => ({ id: "c" + i + "-" + e.r, label: String(txFace(e.r)), entityId: e.id })),
                min: 3,
                max: 3,
                confirm: { id: "ok", label: "Lay them face up", icon: "check" }
            }
        });
    }
}
function txTakeChoice(q, picks) {
    const s = txState;
    if (!s || s.ph !== SV_PH_CHOOSE || txChoices[q])
        return;
    const ranks = [];
    const left = s.hand[q].slice();
    for (const id of picks) {
        const r = Number(id.split("-")[1]);
        if (r >= 0 && r < SV_RANKS && left[r] > 0) {
            left[r] -= 1;
            ranks.push(r);
        }
    }
    if (ranks.length !== 3) {
        txHint(q, "Pick exactly three cards.");
        txChoosing[txSeats[q]] = false;
        txOpenChooseWindows();
        return;
    }
    txChoices[q] = ranks;
    ui.hide("s7210-choose-" + txSeats[q]);
    txHumanMoved = true;
    void txRun(async () => {
        if (txState)
            txRenderHud(txState);
        await txAdvance();
    });
}
// --------------------------------------------------------------------------------- game --
async function txClearTable() {
    world.clearHighlights();
    txLastHighlight = "";
    ui.hide(["s7210-moves", "s7210-count", "s7210-result", "s7210-game"]);
    for (const seat of TX_SEAT_ORDER)
        ui.hide("s7210-choose-" + seat);
    // In the Scripted variant every card on the table is the script's: the pack's own deck, cards dealt into hands, leftovers.
    for (const kind of ["card", "deck"])
        for (const h of await world.getAllObjects({ kind }))
            h.destroy();
    for (const h of await world.getAllObjects({ tag: TX_TAG }))
        h.destroy();
    for (const seat of Object.keys(txHand))
        delete txHand[seat];
    for (const seat of Object.keys(txUp))
        delete txUp[seat];
    for (const seat of Object.keys(txDown))
        delete txDown[seat];
    for (const seat of Object.keys(txChoosing))
        delete txChoosing[seat];
    for (const k of Object.keys(txChoices))
        delete txChoices[Number(k)];
    for (const k of Object.keys(txGone))
        delete txGone[Number(k)];
    txLoose = {};
    txBase = null;
    txDrawPile = null;
    txOutPile = null;
}
async function txStartMatch(setup) {
    txRecording = false;
    if (typeof match === "undefined")
        return;
    const running = match.current();
    if (running && (running.status === "live" || running.status === "opening")) {
        try {
            await match.abort("new game");
        }
        catch (error) {
            world.log("Seven, Twos & Tens: could not stop the previous match (" + txDescribe(error) + ").");
        }
    }
    if (txPractice)
        return;
    try {
        const info = await match.start({ kernel, setup, seats: txSeats });
        txRecording = !!info && info.status === "live";
    }
    catch (error) {
        world.log("Seven, Twos & Tens: this game is not recorded as a match (" + txDescribe(error) + ").");
    }
}
async function txNewGame() {
    txStarting = true;
    try {
        txOver = false;
        txHumanMoved = false;
        txChooseSeats();
        txDrawHud();
        if (!(await txLoadZones())) {
            txHudSet("phase", "Seven, Twos & Tens cannot start");
            txHudSet("howToAll", "The table has no card zones for these seats.");
            return;
        }
        txHudSet("phase", "Dealing a new game");
        for (const k of Object.keys(txHudCache))
            delete txHudCache[k];
        await txClearTable();
        const setup = { seed: Math.floor(Math.random() * 2147483647), first: Math.floor(Math.random() * txSeats.length), decks: txSeats.length >= 5 ? 2 : 1 };
        txSetup = setup;
        await txStartMatch(setup);
        txState = kernel.initial(txSeats, setup);
        world.setGameOver(null);
        const names = txSeats.map((_, q) => txSeatName(q)).join(", ");
        const intro = "New game: " + names + (setup.decks === 2 ? " (two decks)" : "") + ". " + txSeatName(setup.first || 0) + " goes first." + (txPractice ? " Practice: you play against a bot." : "");
        ui.log(intro, { tone: "info" });
        txShowGameControls();
        ui.toast(intro, { tone: "info", icon: "playing_cards", seconds: 6 });
        await txRender();
        await txAdvance();
    }
    finally {
        txStarting = false;
    }
}
/** After a reload: rebuild the game from the running match (setup + recorded moves). */
async function txResume() {
    if (typeof match === "undefined")
        return false;
    const info = match.current();
    if (!info || info.status !== "live")
        return false;
    const setup = match.setup();
    if (!setup || typeof setup.seed !== "number")
        return false;
    try {
        const again = await match.start({ kernel });
        if (!again || again.id !== info.id)
            return false;
    }
    catch (error) {
        return false;
    }
    txSeats = info.participants.map((p) => p.seat);
    txPractice = false;
    if (!(await txLoadZones()))
        return false;
    txDrawHud();
    await txClearTable();
    txSetup = setup;
    let s = kernel.initial(txSeats, setup);
    for (const m of match.moves())
        s = kernel.apply(s, m);
    txState = s;
    txRecording = true;
    txHumanMoved = true;
    ui.log("The running game was picked back up (" + match.moves().length + " moves).", { tone: "info" });
    await txRender();
    await txAdvance();
    return true;
}
/** Practice controls: a new deal at any time, and a bot for the person's seat. */
function txShowGameControls() {
    if (!txPractice) {
        ui.hide("s7210-game");
        return;
    }
    ui.show({
        id: "s7210-game",
        kind: "actions",
        placement: { region: "lower-end", devices: { phone: { menu: true } } },
        actions: [
            { id: "new", label: "New game", icon: "replay" },
            { id: "auto", label: txAutoplay ? "I'll play my cards" : "Let a bot play my cards", icon: txAutoplay ? "person" : "smart_toy" }
        ]
    });
}
async function txGameOver() {
    const s = txState;
    if (!s || s.ph !== SV_PH_OVER)
        return;
    txOver = true;
    world.clearHighlights();
    txLastHighlight = "";
    ui.hide(["s7210-moves", "s7210-count"]);
    const result = s.win === -2 ? { draw: true } : { winner: txSeats[s.win] };
    const headline = s.win === -2 ? "The game is a draw." : txSeatName(s.win) + " is out of cards and wins!";
    const scores = {};
    for (let q = 0; q < txSeats.length; q += 1)
        scores[txSeats[q]] = svCardsLeft(s, q);
    ui.show({
        id: "s7210-result",
        kind: "result",
        headline,
        lines: txSeats.map((seat, q) => txSeatName(q) + ": " + scores[seat] + " card" + (scores[seat] === 1 ? "" : "s") + " left")
    });
    world.setGameOver(result);
    ui.log(headline, { tone: "success" });
    ui.toast(headline, { tone: "success", icon: "emoji_events", seconds: 8 });
    ui.show({
        id: "s7210-game",
        kind: "actions",
        placement: { region: "lower-end" },
        actions: [{ id: "new", label: "New game", icon: "replay" }]
    });
    if (txRecording) {
        txRecording = false;
        match.end(result, { reason: s.win === -2 ? "move limit" : "out of cards", scores }).catch((error) => {
            world.log("Seven, Twos & Tens: the match result was not accepted (" + txDescribe(error) + ").");
        });
    }
}
// --------------------------------------------------------------------------------- events --
/** What one of the script's entities is: a hand card, a face-up or face-down slot, or the pile. */
function txFind(id) {
    for (let q = 0; q < txSeats.length; q += 1) {
        const seat = txSeats[q];
        for (const e of txHand[seat] || [])
            if (e.id === id)
                return { kind: "hand", q, r: e.r, slot: -1 };
        const ups = txUp[seat] || [];
        for (let i = 0; i < ups.length; i += 1)
            if (ups[i] && ups[i].id === id)
                return { kind: "up", q, r: ups[i].r, slot: i };
        const downs = txDown[seat] || [];
        for (let i = 0; i < downs.length; i += 1)
            if (downs[i] && downs[i].id === id)
                return { kind: "down", q, r: -1, slot: i };
    }
    if (txBase && txBase.id === id)
        return { kind: "pile", q: -1, r: -1, slot: -1 };
    for (const key of Object.keys(txLoose))
        if (txLoose[Number(key)].id === id)
            return { kind: "pile", q: -1, r: -1, slot: -1 };
    return null;
}
globalEvents.onObjectClicked.add((object, context) => {
    const s = txState;
    if (!s || txOver)
        return;
    const what = txFind(object.id);
    if (!what)
        return;
    const q = txSeatOf(context.seat, context.actor);
    if (q < 0)
        return;
    if (s.ph === SV_PH_CHOOSE) {
        if (what.kind === "hand" && what.q === q)
            txHint(q, "Pick your face-up cards in the picker.");
        return;
    }
    if (what.kind === "pile") {
        if (s.who === q && svLegalMoves(s).indexOf(SV_M_PICKUP) >= 0)
            void txRun(() => txHumanMove(q, SV_M_PICKUP));
        return;
    }
    if (what.q !== q)
        return;
    const src = svSource(s, q);
    if (what.kind === "hand")
        txOfferPlays(q, what.r);
    else if (what.kind === "up") {
        if (src !== 1)
            txHint(q, src === 0 ? "Play from your hand first." : "Your face-up cards are gone.");
        else
            txOfferPlays(q, what.r);
    }
    else if (what.kind === "down") {
        if (src !== 2)
            txHint(q, "Face-down cards come last: empty your hand and face-up cards first.");
        else
            void txRun(() => txHumanMove(q, SV_M_BLIND + what.slot));
    }
});
/** A hand card dragged out of the hand: onto the pile it is played, anywhere else it goes back. */
globalEvents.onObjectDropped.add((object, context) => {
    void txRun(async () => {
        const s = txState;
        if (!s)
            return;
        const what = txFind(object.id);
        if (!what || what.kind !== "hand")
            return;
        const seat = txSeats[what.q];
        const hand = txZones[seat] && txZones[seat]["HandZone"];
        if (hand && txInZone(hand, object.position, 0.02))
            return;
        // The script's own moves (dealing, laying out a row) are not a person's drag.
        if (context.actor === "Script" || context.actor === "Host" || context.actor === "System")
            return;
