    if (event.widgetId.indexOf("s7210-choose-") === 0) {
        const seat = event.widgetId.slice("s7210-choose-".length);
        const owner = txSeats.indexOf(seat);
        if (owner < 0 || (q !== owner && !txPractice) || event.dismissed)
            return;
        if (event.actionId === "ok" && event.value)
            txTakeChoice(owner, event.value);
