        return;
    txRestartQueued = true;
    void txRun(async () => {
        await world.wait(1.5);
        txRestartQueued = false;
        if (txHumanMoved)
            return;
        const occupied = TX_SEAT_ORDER.filter((seat) => world.getPlayers().some((p) => p.seat === seat));
        const now = occupied.length >= 2 ? occupied.join(",") : "practice";
        const was = txPractice ? "practice" : txSeats.join(",");
